PW=$(cat /tmp/root_pw.txt)
sudo mysql -e "
DELETE FROM mysql.user WHERE User='';
DROP DATABASE IF EXISTS test;
ALTER USER 'root'@'localhost' IDENTIFIED BY [REDACTED];
FLUSH PRIVILEGES;
"
sudo tee /root/.my.cnf > /dev/null <<EOF
[client]
user=root
password=[REDACTED]}
EOF
sudo chmod 600 /root/.my.cnf
